inline bool from_string(const char* str, RulebookIngestionRelationType& out) {
    if (std::strcmp(str, "CLAIM_SUPPORTED_BY") == 0) { out = RulebookIngestionRelationType::CLAIM_SUPPORTED_BY; return true; }
    if (std::strcmp(str, "CLAIM_MATERIALIZES") == 0) { out = RulebookIngestionRelationType::CLAIM_MATERIALIZES; return true; }
    if (std::strcmp(str, "CLAIM_RESOLVED_AGAINST") == 0) { out = RulebookIngestionRelationType::CLAIM_RESOLVED_AGAINST; return true; }
    return false;
}

/// The closed set of kinds a moment can be, exactly as Chapter One of the Voyager book fixes it [01-the-shape-of-a-career.md "The kinds of moments"]. Closed on purpose: the list is the game's ethos, and an open string here would let a seed invent a sixth kind no chapter ever wrote. Lower case, case sensitive, because that is what the seeds say and folding case would accept the typo the enum exists to refuse.
enum class MomentKindKey {
    VIOLENCE,
    JUDGMENT,
    DISCOVERY,
    STANDING,
    LOSS
};

/// Convert MomentKindKey to its string representation.
inline const char* to_string(MomentKindKey value) {
    switch (value) {
        case MomentKindKey::VIOLENCE: return "violence";
        case MomentKindKey::JUDGMENT: return "judgment";
        case MomentKindKey::DISCOVERY: return "discovery";
        case MomentKindKey::STANDING: return "standing";
        case MomentKindKey::LOSS: return "loss";
    }
    return "unknown";
}

/// Parse a string into MomentKindKey. Returns false if the string is not a valid value.
inline bool from_string(const char* str, MomentKindKey& out) {
    if (std::strcmp(str, "violence") == 0) { out = MomentKindKey::VIOLENCE; return true; }
    if (std::strcmp(str, "judgment") == 0) { out = MomentKindKey::JUDGMENT; return true; }
    if (std::strcmp(str, "discovery") == 0) { out = MomentKindKey::DISCOVERY; return true; }
    if (std::strcmp(str, "standing") == 0) { out = MomentKindKey::STANDING; return true; }
    if (std::strcmp(str, "loss") == 0) { out = MomentKindKey::LOSS; return true; }
    return false;
}

/// The three ways a season is spent [01-the-shape-of-a-career.md "Seasons"]. Closed for the same reason as MomentKindKey.
enum class SeasonModeKey {
    PREPARATION,
    PURSUIT,
    QUIET
};

/// Convert SeasonModeKey to its string representation.
inline const char* to_string(SeasonModeKey value) {
    switch (value) {
        case SeasonModeKey::PREPARATION: return "preparation";
        case SeasonModeKey::PURSUIT: return "pursuit";
        case SeasonModeKey::QUIET: return "quiet";
    }
    return "unknown";
}

/// Parse a string into SeasonModeKey. Returns false if the string is not a valid value.
inline bool from_string(const char* str, SeasonModeKey& out) {
    if (std::strcmp(str, "preparation") == 0) { out = SeasonModeKey::PREPARATION; return true; }
    if (std::strcmp(str, "pursuit") == 0) { out = SeasonModeKey::PURSUIT; return true; }
    if (std::strcmp(str, "quiet") == 0) { out = SeasonModeKey::QUIET; return true; }
    return false;
}

/// Typed links from a character to what their life holds.
enum class VoyagerLifeRelationType {
    LIVED
};

/// Convert VoyagerLifeRelationType to its string representation.
inline const char* to_string(VoyagerLifeRelationType value) {
    switch (value) {
        case VoyagerLifeRelationType::LIVED: return "LIVED";
    }
    return "unknown";
}

/// Parse a string into VoyagerLifeRelationType. Returns false if the string is not a valid value.
inline bool from_string(const char* str, VoyagerLifeRelationType& out) {
    if (std::strcmp(str, "LIVED") == 0) { out = VoyagerLifeRelationType::LIVED; return true; }
    return false;
}

/// Entity with a position and orientation in 3D space.
struct Spatial {
    std::optional<float> position_x = std::nullopt;
    std::optional<float> position_y = std::nullopt;
    std::optional<float> position_z = std::nullopt;
    /// Direction entity faces in radians.
    std::optional<float> facing_angle = std::nullopt;
    /// World-position stamp written by createEntityAtPosition and the generators. Legacy duplicate of position_x; declared so the setProperty gate can validate what the engine actually writes (Malleus H1). Unification with position_* is follow-up work.
    std::optional<float> x = std::nullopt;
    /// World-position stamp; legacy duplicate of position_y (see x).
    std::optional<float> y = std::nullopt;
    /// World-position stamp; legacy duplicate of position_z (see x).
    std::optional<float> z = std::nullopt;
    /// Chunk-grid X coordinate, floor(world_x / chunk_size).
    std::optional<int32_t> chunk_x = std::nullopt;
    /// Chunk-grid Y coordinate, floor(world_y / chunk_size).
    std::optional<int32_t> chunk_y = std::nullopt;
};


/// Entity made of a physical material.
struct HasMaterial {
    std::optional<MaterialType> material_type = std::nullopt;
    /// Density in kg/m3.
    std::optional<float> material_density = std::nullopt;
    /// Coulomb friction coefficient.
    std::optional<float> material_friction = std::nullopt;
    /// Tensile strength in Pa.
    std::optional<float> material_strength = std::nullopt;
};


/// Entity that can take damage and die.
struct HasHealth {
    std::optional<float> health = std::nullopt;
    std::optional<float> max_health = std::nullopt;
};


/// Entity that emits light and can be seen from a distance.
struct EmitsLight {
    /// Light intensity (lux).
    std::optional<float> emission_strength = std::nullopt;
    /// Maximum light reach distance.
    std::optional<float> emission_radius = std::nullopt;
};


/// The simple-entity contract read by the engine's simple_entity_activator (src/entities/simple_entity.cpp): one particle built from a uniform size plus RGB color. Runtime keys are the slot names verbatim. Known drift siblings, unification pending an owner ruling: PhysicsRock.color_r/g/b and CelestialBody.moon_r/g/b.
struct HasSimpleAppearance {
    /// Uniform particle size in meters (width = height = thickness for simple entities; also the rock spec's characteristic size).
    std::optional<float> size = std::nullopt;
    /// Red color component, 0..1.
    std::optional<float> r = std::nullopt;
    /// Green color component, 0..1.
    std::optional<float> g = std::nullopt;
    /// Blue color component, 0..1.
    std::optional<float> b = std::nullopt;
};


/// Physical performance attributes of a body component or agent.
struct HasPhysicalCapability {
    /// Force production capacity in Newtons. 0 = non-functional.
    std::optional<float> part_strength = std::nullopt;
    /// Maximum force capacity ceiling in Newtons. Degrades with permanent injury.
    std::optional<float> part_max_strength = std::nullopt;
    /// Range of motion ratio. 0.0 = locked, 1.0 = full ROM.
    std::optional<float> part_flexibility = std::nullopt;
    /// Neural response speed for this part in milliseconds. Lower = faster.
    std::optional<float> part_responsiveness = std::nullopt;
    /// Action cycles before fatigue. Drains with use, recovers with rest.
    std::optional<float> part_endurance = std::nullopt;
};


/// Tissue-level health tracking for body parts. Different damage types affect different tissues.
struct HasTissue {
    /// Muscle tissue integrity 0-100. Affects power production. Damaged by CUT, CRUSH.
    std::optional<float> muscle_health = std::nullopt;
    /// Nerve tissue integrity 0-100. Affects control/speed. Damaged by PIERCE, CRUSH.
    std::optional<float> nerve_health = std::nullopt;
    /// Tendon integrity 0-100. At 0 = limb unusable. Damaged by CUT.
    std::optional<float> tendon_health = std::nullopt;
    /// Bone integrity 0-100. At 0 = fracture. Damaged by CRUSH.
    std::optional<float> bone_health = std::nullopt;
};


/// Entity that produces a detectable scent.
struct HasOdor {
    std::optional<OdorType> odor_type = std::nullopt;
};


/// Carries who owns this body's position. Every body in the world has it, because immobility is always a choice, never an accident of being still.
struct HasSolverAuthority {
    /// Who owns this body's position. Omit for DYNAMIC. Set KINEMATIC to make something genuinely immovable - terrain, a floor, a world. Never try to hold a structure up by leaving it still; stillness is an optimisation the physics undoes on contact.
    std::optional<SolverAuthority> solver_authority = std::nullopt;
};


/// Can be cemented to other bodies through a BONDED_TO relation. bond_strength is how much load the join carries before it gives.
struct Bondable {
    /// Load a BONDED_TO join carries before it gives, in newtons per metre. Around 90000 behaves as rigid cement; small values give under their own weight.
    std::optional<float> bond_strength = std::nullopt;
};


/// Entity that can be damaged or destroyed.
struct Destructible {
    /// Damage required to trigger destruction.
    std::optional<float> damage_threshold = std::nullopt;
    std::optional<EntityModification> modification_state = std::nullopt;
};


/// Entity that grows over time via procedural generation.
struct Growable {
    std::optional<int32_t> growth_iteration = std::nullopt;
    std::optional<bool> is_mature = std::nullopt;
    std::optional<std::string> species = std::nullopt;
    /// Whether deferred growth simulation is active for this entity.
    std::optional<bool> growth_enabled = std::nullopt;
    /// Game-time seconds at which the organism was created.
    std::optional<float> growth_time_created = std::nullopt;
    /// Game-time seconds at which growth was last advanced.
    std::optional<float> growth_time_last_simulated = std::nullopt;
    /// Growth iterations accrued per game year.
    std::optional<float> growth_rate_per_year = std::nullopt;
    /// Iteration count at which the organism is mature.
    std::optional<int32_t> growth_max_iterations = std::nullopt;
    /// Generation algorithm provenance (e.g. space_colonization).
    std::optional<std::string> method = std::nullopt;
};


/// Anything with a stable, globally unique identity. Aligned with BFO Independent Continuant: exists on its own, bears qualities, participates in processes.
struct Identifiable {
    /// Globally unique identifier.
    std::string id = {};
    /// Human-readable name.
    std::optional<std::string> name = std::nullopt;
};


/// Timestamps for creation and last modification. Follows PROV-O temporal patterns.
struct Temporal {
    /// When this was created.
    std::optional<std::string> created_at = std::nullopt;
    /// When this was last modified.
    std::optional<std::string> updated_at = std::nullopt;
};


/// Human-readable description and metadata.
struct Describable {
    /// Free-text description.
    std::optional<std::string> description = std::nullopt;
    /// Arbitrary classification tags.
    std::vector<std::string> tags = {};
};


/// Entity with a lifecycle status.
struct Statusable {
    /// Lifecycle status.
    std::optional<EntityStatus> status = std::nullopt;
};


/// Capability of acting, deciding, or bearing responsibility. Aligned with PROV:Agent and BDI model. Agency is a trait, not a taxonomic position: an entity CAN act, it is not defined by acting. Apply this mixin to any entity class that needs volitional behavior.
struct Agent {
    /// Classification of the agent. Domain projects should constrain this to an enum.
    std::optional<std::string> agent_type = std::nullopt;
};


/// Root class for all identifiable, enduring things. Aligned with BFO:Independent Continuant. Every domain object that persists through time and needs identity extends this.
struct Entity : public Identifiable, public Temporal, public Describable {
};


