/// Singleton entity holding the global physics parameters a world is seeded with. These three are what KGModule::seedPhysicsConstants writes; they were undeclared properties until 2026-08-13. This is per-world KG configuration, not the solver constants registry: those are build-time inputs generated into the engine (INV-29), and the solver never reads the KG.
struct PhysicsConstants : public Entity {
    /// Gravitational acceleration along world Z, m/s2. Negative points down. Earth default -9.8. The world-Z framing is legacy: this is a seed value for a world, not a licence for solver code to assume an up axis, which INV-6 forbids.
    std::optional<float> gravity_z = std::nullopt;
    /// Global air drag coefficient, dimensionless. 0 disables it, which is the current default.
    std::optional<float> air_resistance = std::nullopt;
    /// Coulomb friction coefficient used where a pair declares none, dimensionless. Default 0.5.
    std::optional<float> default_friction = std::nullopt;
};


/// Physics constraint between two particles.
struct Constraint : public Entity {
    GluonType gluon_type = {};
    /// Constraint stiffness in N/m.
    float stiffness = {};
    /// Damping coefficient in Ns/m.
    std::optional<float> damping = std::nullopt;
    /// Force threshold for constraint failure.
    std::optional<float> breaking_force = std::nullopt;
    /// Stable KGParticleID of the first constraint endpoint.
    std::optional<int32_t> particle_a = std::nullopt;
    /// Stable KGParticleID of the second constraint endpoint.
    std::optional<int32_t> particle_b = std::nullopt;
    /// Rest length of the constraint in meters.
    std::optional<float> rest_distance = std::nullopt;
    /// Undamaged stiffness in N/m as serialized by the generators. Sibling of the required `stiffness` slot; the generators write this key today (schema/writer drift, noted by Malleus H1).
    std::optional<float> base_stiffness = std::nullopt;
    /// Semantic joint name (e.g. left_hip) when the constraint is a skeletal joint.
    std::optional<std::string> joint_name = std::nullopt;
    /// Owning-entity back-reference the totem generator serializes on its constraints. Relation-shaped data stored as a property; declared as written (Malleus H1), migration to a real relation is follow-up work.
    std::optional<int32_t> entity_id = std::nullopt;
    /// Attachment offset of endpoint A, local X, meters.
    std::optional<float> offset_a_x = std::nullopt;
    /// Attachment offset of endpoint A, local Y, meters.
    std::optional<float> offset_a_y = std::nullopt;
    /// Attachment offset of endpoint A, local Z, meters.
    std::optional<float> offset_a_z = std::nullopt;
    /// Attachment offset of endpoint B, local X, meters.
    std::optional<float> offset_b_x = std::nullopt;
    /// Attachment offset of endpoint B, local Y, meters.
    std::optional<float> offset_b_y = std::nullopt;
    /// Attachment offset of endpoint B, local Z, meters.
    std::optional<float> offset_b_z = std::nullopt;
};


/// Declares how particles carrying this profile interact with other particles: a category bit and a collides-with mask consulted at contact broad phase, plus optional medium parameters (drag, buoyancy, directional field force) applied to particles overlapping a filtered pair. Profile 0 is the engine default: collide with everything, no medium.
struct ParticleInteractionProfile : public Entity {
    /// Which interaction category bit (0-31) this profile occupies.
    std::optional<int32_t> category_bit = std::nullopt;
    /// Bitmask of category bits this profile exchanges rigid contact with.
    std::optional<int32_t> collides_with_mask = std::nullopt;
    /// Medium drag applied to particles inside this profile's volume (0 = none).
    std::optional<float> drag_coefficient = std::nullopt;
    /// Buoyant acceleration share against gravity for intruders (0 = none, 1 = neutral).
    std::optional<float> buoyancy_factor = std::nullopt;
    /// Directional field force X applied to intruders, Newtons.
    std::optional<float> field_fx = std::nullopt;
    /// Directional field force Y applied to intruders, Newtons.
    std::optional<float> field_fy = std::nullopt;
    /// Directional field force Z applied to intruders, Newtons.
    std::optional<float> field_fz = std::nullopt;
};


/// A declarative EVENT rule, executed by the interaction system. Three separable questions, one slot each: `trigger` is which engine event source to listen to (closed), `condition` is whether this occurrence matters (open), `effect` is what to do (open).
/// Event rules are pushed and fire once per episode. They are not the same mechanism as capability response rules, which are state predicates pulled over the KG and safe to re-evaluate; see docs/GAME_LAYER.md for when to reach for which.
struct TransformationRule : public Entity {
    /// WHICH engine event source this rule listens to. Genuinely closed: each value is a queue the interaction system owns, and a game cannot add one without engine code. See TransformationTrigger for the vocabulary and the case-normalization rule.
    std::optional<TransformationTrigger> trigger = std::nullopt;
    /// WHETHER this rule cares about a given occurrence, evaluated against the event context once the trigger has selected it. Open by design: engine built-ins plus anything a game registers. Syntax "<name>" or "<name>:<args>". Empty means unconditional.
    /// Engine built-ins for ON_CONTACT:
    ///   with_type:<EntityType>   the other party resolves to this type
    ///   impact_above:<m/s>       approach speed exceeds a threshold
    ///
    /// This slot generalizes trigger_profile, which is the same idea hardcoded to one comparison. New rules should prefer condition.
    std::optional<std::string> condition = std::nullopt;
    /// WHAT this rule does when it fires. Open by design: the TransformationEffect enum lists the engine built-ins, and a game-registered effect name is an equally legal value here, which is why this slot is a string rather than typed to that enum.
    std::optional<std::string> effect = std::nullopt;
    /// Profile id the effect targets (for swap_profile).
    std::optional<int32_t> target_profile = std::nullopt;
    /// Effect duration in seconds (for timed effects).
    std::optional<float> duration_s = std::nullopt;
    /// Interaction profile id a volume/contact trigger binds to (0 = any profile fires the rule).
    std::optional<int32_t> trigger_profile = std::nullopt;
};


/// Something that happens at a point or over an interval. Aligned with BFO:Occurrent / PROV:Activity. Instantaneous events use occurred_at. Processes with duration use started_at / ended_at (Allen's interval algebra).
struct Event : public Identifiable, public Temporal {
    /// Classification of the event. Domain projects should constrain this to an enum.
    std::string event_type = {};
    /// When the event happened (instantaneous events).
    std::optional<std::string> occurred_at = std::nullopt;
    /// When a duration event began.
    std::optional<std::string> started_at = std::nullopt;
    /// When a duration event ended.
    std::optional<std::string> ended_at = std::nullopt;
    /// ID of the event or agent that caused this event. Follows PROV-O wasInformedBy / wasAssociatedWith pattern.
    std::optional<std::string> caused_by = std::nullopt;
};


/// Something that happens in the game world.
struct WorldEvent : public Event {
    /// ID of the entity that caused the event.
    std::optional<std::string> source_entity_id = std::nullopt;
    /// ID of the entity affected by the event.
    std::optional<std::string> target_entity_id = std::nullopt;
    /// Event payload keys (parallel to payload_values). Populated from rule.N.payload.* KG properties when emit_event fires.
    std::vector<std::string> payload_keys = {};
    /// Event payload values (parallel to payload_keys).
    std::vector<std::string> payload_values = {};
};


/// Two entities physically collide. Carries the contact itself, not just the fact of it: an event rule can only be as specific as the occurrence it reads, and a consequence (knockback, absorption, where to spawn blood) needs the geometry and the energy.
/// source/target_entity_id name the two creatures; source/target_part_id name the body parts that actually touched, because armour and injury are per-part. The normal comes from contact geometry, never from a world-up assumption, so it is meaningful on walls, ceilings and in zero-g.
struct CollisionEvent : public WorldEvent {
    /// Magnitude of collision impact in Newtons.
    std::optional<float> collision_force = std::nullopt;
    /// Contact normal X, unit, pointing from source toward target.
    std::optional<float> normal_x = std::nullopt;
    /// Contact normal Y, unit, pointing from source toward target.
    std::optional<float> normal_y = std::nullopt;
    /// Contact normal Z, unit, pointing from source toward target.
    std::optional<float> normal_z = std::nullopt;
    /// World-space contact point X.
    std::optional<float> contact_x = std::nullopt;
    /// World-space contact point Y.
    std::optional<float> contact_y = std::nullopt;
    /// World-space contact point Z.
    std::optional<float> contact_z = std::nullopt;
    /// Overlap depth at the contact, metres.
    std::optional<float> penetration = std::nullopt;
    /// Relative velocity along the contact normal, m/s. NEGATIVE means the pair is approaching; positive means separating. This is the energy term a consequence scales with, and the sign convention is the solver's, not a reinterpretation.
    std::optional<float> approach_speed = std::nullopt;
    /// KG EntityID of the body part on the source side, decimal string. Matches the source_entity_id/target_entity_id convention on WorldEvent rather than introducing a second id encoding.
    std::optional<std::string> source_part_id = std::nullopt;
    /// KG EntityID of the body part on the target side, decimal string.
    std::optional<std::string> target_part_id = std::nullopt;
};


/// An entity takes damage.
struct DamageEvent : public WorldEvent {
    std::optional<DamageType> damage_type = std::nullopt;
    /// Amount of damage inflicted.
    std::optional<float> damage_amount = std::nullopt;
};


/// An entity is created in the world.
struct SpawnEvent : public WorldEvent {
};


/// A living entity dies.
struct DeathEvent : public WorldEvent {
};


/// An agent perceives another entity.
struct PerceptionEvent : public WorldEvent {
    /// Perception memory state at time of event.
    std::optional<MemoryLayer> memory_layer = std::nullopt;
};


/// A relation between two entities was created or removed.
struct RelationEvent : public WorldEvent {
    /// The type of relation (has_part, contains, depends_on, etc.). Domain projects should constrain this to an enum.
    std::string relation_type = {};
};


/// A particle pair overlapping in broad phase was excluded from narrow-phase contact by their interaction profiles (start of a pass-through episode).
struct ContactFilteredEvent : public WorldEvent {
    /// Interaction profile of the first particle in the filtered pair.
    std::optional<int32_t> profile_a = std::nullopt;
    /// Interaction profile of the second particle in the filtered pair.
    std::optional<int32_t> profile_b = std::nullopt;
};


/// A particle entered (entered=true) or exited (entered=false) the volume of a particle whose profile declares a medium.
struct VolumeEvent : public WorldEvent {
    /// True on volume entry, false on exit.
    std::optional<bool> entered = std::nullopt;
    /// Profile id of the medium volume involved.
    std::optional<int32_t> medium_profile = std::nullopt;
};


/// A TransformationRule fired on a particle.
struct TransformationEvent : public WorldEvent {
    /// Name of the transformation rule that fired.
    std::optional<std::string> rule_name = std::nullopt;
};


/// A die roll the ENGINE performed: seeded, journaled, citable by id. Games and referees receive rolls as facts through this event; nothing outside the dice service may assert a result (see docs/RPG_MODULE.md, "the referee cannot roll").
struct DiceRollEvent : public WorldEvent {
    /// Monotonic id of the roll, unique per session, citable.
    std::optional<int32_t> roll_id = std::nullopt;
    /// The expression rolled, canonical form ("2D6+1"). EXECUTED, and by a named thing: DiceService::parse turns this string into a DiceExpression and DiceService::roll evaluates it (include/logosphere/core/dice_service.h:56,110). Recorded here because a formula-shaped slot is the fleet's most common way of writing knowledge down and never running it, and the only defence against that is naming the executor next to the slot. If the parser ever stops being the sole reader of this string, this line is wrong and the slot has become documentation.
    std::optional<std::string> dice_expression = std::nullopt;
    /// Individual die results, comma-separated, in roll order.
    std::optional<std::string> roll_values = std::nullopt;
    /// (Sum of the dice plus the modifier) times the multiplier.
    std::optional<int32_t> roll_total = std::nullopt;
    /// Named RNG stream the roll came from (e.g. "chargen"). Streams are independently seeded so a session replays deterministically.
    std::optional<std::string> roll_stream = std::nullopt;
    /// What the roll was for, in the roller's words.
    std::optional<std::string> roll_purpose = std::nullopt;
};


/// A continuously derived quality that emerges from patterns of Events between Entities. Aligned with BFO:Specifically Dependent Continuant (Quality) and SSN/SOSA:Observation. A Signal inheres in its bearer(s) — it does not exist independently. It is computed, not asserted: derived on demand from the Event log and Entity graph via a named algorithm. Domain projects define signal types, algorithms, and interpretation semantics. The Signal class captures the universal pattern: something measurable that emerges from activity, has a current value, and is recomputable from the underlying data.
struct Signal : public Identifiable, public Temporal {
    /// Classification of the signal. Domain projects should constrain this to an enum. Examples: trust_score, health_score, centrality.
    std::string signal_type = {};
    /// Current computed value. Interpretation is signal-type specific. Often 0.0–1.0 but not constrained at the root level (domain decides range and semantics).
    std::optional<float> value = std::nullopt;
    /// Name or reference of the computation that produces this signal. Domain projects should document algorithms and constrain this to an enum. Examples: appleseed, pagerank, ewma, linear_decay.
    std::optional<std::string> algorithm = std::nullopt;
    /// ID of the entity from whose perspective this signal is computed. Null for global/objective signals (e.g., graph density). Set for subjective signals (e.g., trust computed from one agent's viewpoint).
    std::optional<std::string> perspective = std::nullopt;
    /// When this signal value was last computed.
    std::optional<std::string> computed_at = std::nullopt;
    /// ID of the entity (or relationship) this signal inheres in. Required because a Signal cannot exist without a bearer (BFO: dependent continuant).
    std::string bearer_id = {};
};


/// A typed, directed edge between two entities. Reified as a class so relations can carry metadata (strength, confidence, temporal validity).
struct Relation : public Identifiable, public Temporal {
    /// The type of relation (has_part, contains, depends_on, etc.). Domain projects should constrain this to an enum.
    std::string relation_type = {};
    /// Reference to the source Entity.
    Entity source_id = {};
    /// Reference to the target Entity.
    Entity target_id = {};
    /// Weight or confidence of the relation (0.0 to 1.0).
    std::optional<float> strength = std::nullopt;
};


/// Abstract parent of the engine's world relations. One concrete subclass per member of WorldRelationType, each pinning its own predicate and declaring its own endpoints.
/// It is abstract because a relation class that leaves relation_type open across an enum is not one relation, it is a family. Malleus refuses that shape ("Concrete relation must fix relation_type with equals_string") and the refusal is right: an edge whose predicate is only known at write time cannot have a checkable domain and range, so endpoint validation degenerates to "does this name exist".
struct WorldRelation : public Relation {
};


/// Composition: a humanoid has_part a torso. Endpoints are Entity from evidence, not neglect. 81 createRelation sites in C++ plus 1518 seed ops, spanning humanoid to torso, Procedure to ProcedureStep, RollableTable to TableEntry, LookupTable to CharacteristicModifierEntry, and OutcomeSequence to OutcomeStep. There is no narrower pair that covers them.
struct HasPartRelation : public WorldRelation {
};


/// Spatial subdivision: an arm has_regional_part a forearm. No creation site in C++ or seeds as of 2026-08-16, so there is nothing to learn its endpoints from. Entity until evidenced.
struct HasRegionalPartRelation : public WorldRelation {
};


/// Physics constraint link. Three creation sites, all body to constraint, but the body side spans humanoid, totem and the generic entity generator, and the constraint side has no class of its own in this schema to narrow to.
struct HasConstraintRelation : public WorldRelation {
};


/// Spatial containment: a chest contains an item. Four creation sites spanning strata floor to layer, floor to tile, and torso to arm. Heterogeneous, so Entity.
struct ContainsRelation : public WorldRelation {
};


/// Physical support: a floor supports an entity. One site and it is a test. No production creation site, so the shape is unevidenced.
struct SupportsRelation : public WorldRelation {
};


/// A light source reaches an entity. The one relation whose endpoints are KNOWN rather than guessed: only a LightSource illuminates, which is what that class exists for, and only something in the world can be lit. Both classes are declared in this file, so the root can name them.
struct IlluminatesRelation : public WorldRelation {
};


/// Fire spread between entities. No creation site anywhere in the repository, so there is nothing to learn its shape from yet.
struct BurnsRelation : public WorldRelation {
};


/// An agent perceives a target entity. One site and it is a test (creature to torso). Anything can perceive anything until the perception layer says otherwise.
struct PerceivesRelation : public WorldRelation {
};


/// A system entity manages another entity. Two sites, both the chunk system to a chunk's entity. Neither side has a class in this schema to narrow to.
struct ManagesRelation : public WorldRelation {
};


/// Direct bond between two bodies, the engine's cement. The bond is a physical constraint at bond_strength; strong bonds make many particles behave as one rigid body, weak ones give under load. Use it to fix things in place relative to each other rather than to the world. No createRelation site: bonds are made through the gluon path, so the KG edge has no writer to learn endpoints from.
struct BondedToRelation : public WorldRelation {
};


/// A narrower thing refines a broader one: Slug Rifle SPECIALIZES Gun Combat in a skill cascade. Every occurrence measured is Skill to Skill, and Skill is a rulebook-pack class, so this file cannot name it. The pack may declare its own narrowed subclass; the root keeps the generic vocabulary.
struct SpecializesRelation : public WorldRelation {
};


/// Explicit scope in which knowledge originates or grows.
struct KnowledgeContext : public Entity {
    /// Globally unique immutable identity of a KnowledgeContext.
    std::string context_key = {};
};


/// Immutable authored layer owned by seed ingestion.
struct SourceLayerContext : public KnowledgeContext {
    /// Authored layer declared by a seed envelope.
    std::string source_layer = {};
};


/// Exact source document and revision represented by a seed.
struct SourceDocumentContext : public KnowledgeContext {
    /// Authored layer declared by a seed envelope.
    std::string source_layer = {};
    /// Path of the source document relative to its source root.
    std::string source_file = {};
    /// Legacy Git commit pin of a SourceDocumentContext. New source revision observations use source_revision because source systems are not required to be Git repositories.
    std::string source_commit = {};
    /// Immutable parent source layer of a document context.
    SourceLayerContext source_layer_context = {};
};


/// Mutable host-defined knowledge scope.
struct RuntimeContext : public KnowledgeContext {
    /// Host-defined runtime scope vocabulary.
    std::string context_kind = {};
};


/// Portable immutable identity for content entities. Identity is the tuple of context, exact concrete type, and machine key. Display names and source aliases never participate in resolution.
struct Addressable {
    /// Immutable context component of portable entity identity.
    KnowledgeContext identity_context = {};
    /// Immutable machine key within a context and concrete type.
    std::string entity_key = {};
};


/// Exact immutable bytes of one source representation. A new byte sequence is a new context even when it represents the same logical document or edition.
struct SourceRepresentationContext : public KnowledgeContext {
    /// Authored layer declared by a seed envelope.
    std::string source_layer = {};
    /// Path of the source document relative to its source root.
    std::string source_file = {};
    /// Immutable parent source layer of a document context.
    SourceLayerContext source_layer_context = {};
    /// Closed media kind governing valid primary selectors.
    SourceMediaType source_media_type = {};
    /// Cryptographic algorithm used by source_digest.
    SourceDigestAlgorithm source_digest_algorithm = {};
    /// Digest of the exact source representation bytes.
    std::string source_digest = {};
    /// Exact size of the source representation in bytes.
    int32_t source_byte_length = {};
};


/// Immutable observation that one exact content-addressed representation occurred at one source-system revision. Each representation/revision pair is independent, so later observations never mutate earlier provenance.
struct SourceRevisionObservation : public Entity, public Addressable {
    /// Immutable context component of portable entity identity.
    SourceRepresentationContext identity_context = {};
    /// Immutable machine key within a context and concrete type.
    std::string entity_key = {};
    /// Exact source-system revision retained in a separate provenance observation. Revision does not participate in content identity; exact bytes do.
    std::string source_revision = {};
};


/// Exact immutable source corpus used by one ingestion run. Its identity is the authored source layer plus the digest of its canonical manifest. Source revision observations carry provenance separately; revisions do not participate in the representation or manifest identity.
struct IngestionEditionContext : public KnowledgeContext {
    /// Authored layer declared by a seed envelope.
    std::string source_layer = {};
    /// Immutable parent source layer of a document context.
    SourceLayerContext source_layer_context = {};
    /// Canonical encoding used to produce the source manifest digest.
    SourceManifestFormat source_manifest_format = {};
    /// Cryptographic algorithm used by source_manifest_digest.
    SourceDigestAlgorithm source_manifest_digest_algorithm = {};
    /// Digest of the edition's canonical source manifest.
    std::string source_manifest_digest = {};
    /// Exact number of representations in the source manifest.
    int32_t source_representation_count = {};
};


/// Typed coordinates selecting one fragment of a source representation. Selector subclasses own their coordinate grammar; no discriminator string chooses semantics at runtime.
struct SourceSelector : public Entity, public Addressable {
    /// Immutable context component of portable entity identity.
    SourceRepresentationContext identity_context = {};
};


/// Half-open byte range [start, end) within one immutable source representation. Equal bounds select an empty leaf.
struct ByteRangeSelector : public SourceSelector {
    /// Inclusive zero-based byte position in a representation.
    int32_t source_byte_start = {};
    /// Exclusive zero-based byte position in a representation.
    int32_t source_byte_end = {};
};


/// Supporting exact text plus optional immediate context. It aids inspection and convergence checks but never owns leaf identity.
struct TextQuoteSelector : public SourceSelector {
    /// Exact decoded text expected at the primary selector.
    std::string source_quote_exact = {};
    /// Optional text immediately before the selected text.
    std::optional<std::string> source_quote_prefix = std::nullopt;
    /// Optional text immediately after the selected text.
    std::optional<std::string> source_quote_suffix = std::nullopt;
};


/// One source representation plus its canonical primary selector. An optional quote selector is supporting evidence and must converge on the same fragment.
struct SourceTarget : public Entity, public Addressable {
    /// Immutable context component of portable entity identity.
    SourceRepresentationContext identity_context = {};
    /// Exact immutable source representation being selected.
    SourceRepresentationContext target_representation = {};
    /// Canonical selector that owns target identity.
    SourceSelector target_primary_selector = {};
    /// Optional supporting quote required to match the primary.
    std::optional<TextQuoteSelector> target_quote_selector = std::nullopt;
};


/// Explicit assertion that one exact UTF-8 representation is partitioned completely by its source targets and typed exclusions. Presence enables the mechanical exact-cover gate; absence makes no completeness claim.
struct CompleteSourcePartition : public Entity, public Addressable {
    /// Immutable context component of portable entity identity.
    SourceRepresentationContext identity_context = {};
    /// Immutable machine key within a context and concrete type.
    std::string entity_key = {};
};


/// Exact source bytes excluded from semantic leaves for one closed reason. Exclusions remain visible partition records; they never silently discard unclassified content.
struct SourceExclusion : public Entity, public Addressable {
    /// Immutable context component of portable entity identity.
    SourceRepresentationContext identity_context = {};
    /// Immutable machine key within a context and concrete type.
    std::string entity_key = {};
    /// Exact byte range omitted from semantic source leaves.
    ByteRangeSelector exclusion_selector = {};
    /// Closed reason the selected bytes are non-content.
    SourceExclusionKind exclusion_kind = {};
};


